mapper.select:
SELECT

FROM EVENT_NAMETAG_LOG N
WHERE N.SEQ = #{seq}

SELECT EXISTS(
    SELECT 1 FROM EVENT_NAMETAG_LOG WHERE PARTICIPANT_SEQ = #{participantSeq}
)

mapper.insert:
INSERT INTO EVENT_NAMETAG_LOG (
    PARTICIPANT_SEQ, PRINT_TIME, TEMPLATE_TYPE, PRINT_BY
) VALUES (
    #{participantSeq}, NOW(), #{templateType}, #{printBy}
)

mapper.delete:
DELETE N FROM EVENT_NAMETAG_LOG N
INNER JOIN EVENT_PARTICIPANT P ON N.PARTICIPANT_SEQ = P.SEQ
WHERE P.EVENT_SEQ = #{eventSeq}
